import type { Transition } from "motion/react";

export const easeOut = [0.23, 1, 0.32, 1] as const;

export const easeInOut = [0.77, 0, 0.175, 1] as const;

export const duration = {
  fast: 0.14,
  base: 0.2,
  slow: 0.28,
} as const;

export const springSnappy = {
  type: "spring",
  duration: 0.24,
  bounce: 0,
} as const satisfies Transition;

export const springLayout = {
  type: "spring",
  duration: 0.3,
  bounce: 0,
} as const satisfies Transition;

export function transitionFor(
  reduceMotion: boolean | null,
  transition: Transition,
): Transition {
  return reduceMotion ? { duration: 0 } : transition;
}

import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

"use client";

import {
  animate,
  createGeneratorEasing,
  generateLinearEasing,
  spring,
  type Transition,
  useReducedMotion,
} from "motion/react";
import { type ReactElement, useLayoutEffect, useRef } from "react";
import { duration, easeOut, springSnappy, transitionFor } from "./motion";
import { cn } from "./utils";

const collectionItems =
  "[role=option], [role=menuitem], [role=menuitemradio], [role=menuitemcheckbox], [role=row]";

export const itemHighlightRing =
  "focus-visible:outline-1 focus-visible:outline-solid focus-visible:-outline-offset-1 focus-visible:outline-ring in-data-[item-highlight=ring]:focus-visible:outline-none forced-colors:focus-visible:outline-2 forced-colors:focus-visible:outline-solid forced-colors:focus-visible:-outline-offset-2";

const focusVisible =
  ":is([data-rac][data-focus-visible], :not([data-rac]):focus-visible)";

const fade = { duration: duration.fast, ease: easeOut } satisfies Transition;

const snap = { duration: 0 } satisfies Transition;

const curve = createGeneratorEasing(
  { bounce: springSnappy.bounce, duration: springSnappy.duration * 1000 },
  100,
  spring,
);

const glideTiming = {
  duration: curve.duration * 1000,
  easing: generateLinearEasing(curve.ease, curve.duration * 1000),
  fill: "forwards",
} satisfies KeyframeEffectOptions;

type Move = "glide" | "snap";

type Point = { x: number; y: number };

type Box = Point & { width: number; height: number; radius: string };

type Layer =
  | { kind: "hidden" }
  | { kind: "leaving" }
  | { kind: "shown"; target: HTMLElement; box: Box; ring: boolean };

type Flight = { from: Point; to: Point };

type Pointer = Point & {
  over: EventTarget | null;
  item: HTMLElement | null;
};

const translate = ({ x, y }: Point) => `translate(${x}px, ${y}px)`;

const position = (animation: Animation, { from, to }: Flight): Point => {
  const progress = curve.ease(
    Math.min(1, Number(animation.currentTime ?? 0) / glideTiming.duration),
  );
  return {
    x: from.x + (to.x - from.x) * progress,
    y: from.y + (to.y - from.y) * progress,
  };
};

export interface ItemHighlightProps {
  items?: string;
  placement?: "over" | "under";
  ring?: boolean;
  className?: string;
}

export function ItemHighlight({
  items = collectionItems,
  placement = "over",
  ring = false,
  className,
}: ItemHighlightProps) {
  const ref = useRef<HTMLSpanElement>(null);
  const reduceMotion = useReducedMotion();

  useLayoutEffect(() => {
    const layer = ref.current;
    const container = layer?.parentElement;
    if (!layer || !container) return;
    if (
      placement === "under" &&
      container.parentElement?.closest(
        ":has(> [data-slot=item-highlight][data-placement=under])",
      )
    )
      return;
    const rest = placement === "under" ? "under" : "fill";
    const sizeTransition = transitionFor(reduceMotion, springSnappy);
    const focusedItem = `:is(${items})${focusVisible}`;
    const virtualItem = `:is(${items})[data-focused]`;
    let focused: HTMLElement | null = null;
    let last: "pointer" | "focus" = "focus";
    let pointer: Pointer | null = null;
    let state: Layer = { kind: "hidden" };
    let flight: Flight | null = null;
    const glideEffect = new KeyframeEffect(layer, null, glideTiming);
    const glide = new Animation(glideEffect);

    const owned = (node: Element | null): node is HTMLElement =>
      node instanceof HTMLElement &&
      node.closest("[data-item-highlight], [data-empty]") === container &&
      !container.hasAttribute("data-empty");
    const itemAt = (node: Element, previous: HTMLElement | null) => {
      const item = node.closest(items);
      if (!item) return node.querySelector(items) ? previous : null;
      return owned(item) &&
        !item.matches("[data-disabled], [aria-disabled=true]")
        ? item
        : null;
    };
    const live = (item?: HTMLElement | null) =>
      item && container.contains(item) ? item : null;

    const measure = (target: HTMLElement, origin: Element, radius: string) => {
      let x = 0;
      let y = 0;
      for (let node: HTMLElement | null = target; node && node !== origin; ) {
        x += node.offsetLeft;
        y += node.offsetTop;
        node = node.offsetParent as HTMLElement | null;
        if (node && node !== origin) {
          x += node.clientLeft;
          y += node.clientTop;
        }
      }
      return {
        x,
        y,
        width: target.offsetWidth,
        height: target.offsetHeight,
        radius,
      };
    };

    const slide = (to: Point, from: Point | null, move: Move) => {
      if (from && to.x === from.x && to.y === from.y) return;
      const start = from && (flight ? position(glide, flight) : from);
      if (!start || move === "snap" || reduceMotion) {
        glide.cancel();
        flight = null;
        layer.style.transform = translate(to);
        return;
      }
      glideEffect.setKeyframes({
        transform: [translate(start), translate(to)],
      });
      glide.currentTime = 0;
      glide.play();
      flight = { from: start, to };
    };

    const place = (box: Box, from: Box | null, move: Move) => {
      slide(box, from, move);
      if (!from || box.width !== from.width || box.height !== from.height)
        animate(
          layer,
          { width: box.width, height: box.height },
          from && move === "glide" ? sizeTransition : snap,
        );
      if (!from || box.radius !== from.radius)
        animate(layer, { borderRadius: box.radius }, snap);
    };

    const paintRing = (on: boolean) => {
      if (on === (state.kind === "shown" && state.ring)) return;
      layer.toggleAttribute("data-ring", on);
      container.setAttribute("data-item-highlight", on ? "ring" : rest);
    };

    const resize = new ResizeObserver((entries) => {
      const unchanged = entries.every(
        ({ target, borderBoxSize: [size] }) =>
          state.kind === "shown" &&
          target === state.target &&
          Math.round(size.inlineSize) === state.box.width &&
          Math.round(size.blockSize) === state.box.height,
      );
      if (!unchanged) render("glide");
    });

    const hide = () => {
      if (state.kind !== "shown") return;
      paintRing(false);
      resize.unobserve(state.target);
      const leaving: Layer = { kind: "leaving" };
      state = leaving;
      animate(layer, { opacity: 0 }, fade).then(() => {
        if (state !== leaving) return;
        state = { kind: "hidden" };
        animate(layer, { width: 0, height: 0 }, snap);
      });
    };

    const render = (move: Move) => {
      const origin = layer.offsetParent;
      const target =
        origin &&
        (last === "pointer"
          ? (live(pointer?.item) ?? live(focused))
          : (live(focused) ?? live(pointer?.item)));
      if (!target) return hide();
      const kept =
        state.kind === "shown" && state.target === target ? state : null;
      const same = kept !== null;
      const box = measure(
        target,
        origin,
        kept?.box.radius ?? getComputedStyle(target).borderRadius,
      );
      place(
        box,
        state.kind === "shown" ? state.box : null,
        same ? "snap" : move,
      );
      if (state.kind !== "shown") animate(layer, { opacity: 1 }, fade);
      if (!same) {
        if (state.kind === "shown") resize.unobserve(state.target);
        resize.observe(target);
      }
      const onTarget =
        ring && target === focused && target.matches(focusVisible);
      paintRing(onTarget);
      state = { kind: "shown", target, box, ring: onTarget };
    };

    const first = (selector: string) => {
      for (const node of container.querySelectorAll(selector))
        if (owned(node)) return node;
      return null;
    };
    const syncFocus = () => {
      const next =
        first(focusedItem) ??
        (container.contains(document.activeElement)
          ? null
          : first(virtualItem));
      if (next !== focused) {
        focused = next;
        last = "focus";
      }
      render("glide");
    };
    const onPointerMove = (event: PointerEvent) => {
      if (event.pointerType === "touch") return;
      if (pointer?.over === event.target && last === "pointer") {
        pointer.x = event.clientX;
        pointer.y = event.clientY;
        return;
      }
      pointer = {
        x: event.clientX,
        y: event.clientY,
        over: event.target,
        item:
          event.target instanceof Element
            ? itemAt(event.target, pointer?.item ?? null)
            : null,
      };
      last = "pointer";
      render("glide");
    };
    const onPointerLeave = (event: PointerEvent) => {
      if (event.pointerType === "touch") return;
      pointer = null;
      render("glide");
    };
    const onScroll = () => {
      if (!pointer) return;
      const over = document.elementFromPoint(pointer.x, pointer.y);
      if (over === pointer.over) return;
      const item =
        over && container.contains(over) ? itemAt(over, pointer.item) : null;
      const moved = item !== pointer.item;
      pointer = { ...pointer, over, item };
      if (moved) render("snap");
    };

    const mutations = new MutationObserver(syncFocus);
    container.setAttribute("data-item-highlight", rest);
    mutations.observe(container, {
      subtree: true,
      childList: true,
      attributeFilter: ["data-focus-visible", "data-focused"],
    });
    resize.observe(container);
    container.addEventListener("pointermove", onPointerMove);
    container.addEventListener("pointerleave", onPointerLeave);
    container.addEventListener("focusin", syncFocus);
    container.addEventListener("focusout", syncFocus);
    document.addEventListener("scroll", onScroll, {
      capture: true,
      passive: true,
    });
    syncFocus();
    return () => {
      mutations.disconnect();
      resize.disconnect();
      container.removeEventListener("pointermove", onPointerMove);
      container.removeEventListener("pointerleave", onPointerLeave);
      container.removeEventListener("focusin", syncFocus);
      container.removeEventListener("focusout", syncFocus);
      document.removeEventListener("scroll", onScroll, { capture: true });
      container.removeAttribute("data-item-highlight");
      layer.removeAttribute("data-ring");
      glide.cancel();
      animate(layer, { opacity: 0, width: 0, height: 0 }, snap);
    };
  }, [items, placement, ring, reduceMotion]);

  return (
    <span
      ref={ref}
      aria-hidden="true"
      data-slot="item-highlight"
      data-placement={placement}
      className={cn(
        "pointer-events-none absolute top-0 left-0 bg-highlight opacity-0 forced-colors:hidden data-ring:outline-1 data-ring:outline-solid data-ring:-outline-offset-1 data-ring:outline-[color-mix(in_oklab,var(--ring),var(--foreground)_20%)]",
        placement === "over" ? "z-10" : "-z-10",
        className,
      )}
    />
  );
}

type DivRender<T> = (
  props: React.JSX.IntrinsicElements["div"],
  renderProps: T,
) => ReactElement;

export function withItemHighlight<T>(
  render: DivRender<T> | undefined,
  highlight?: ItemHighlightProps,
): DivRender<T> {
  return (props, renderProps) => {
    const next = {
      ...props,
      className: cn("relative isolate", props.className),
      children: (
        <>
          <ItemHighlight {...highlight} />
          {props.children}
        </>
      ),
    };
    return render ? render(next, renderProps) : <div {...next} />;
  };
}

"use client";

import {
  ListBox as AriaListBox,
  ListBoxItem as AriaListBoxItem,
  composeRenderProps,
  type ListBoxItemProps,
  type ListBoxProps,
} from "react-aria-components";
import { cn } from "./utils";
import { itemHighlightRing, withItemHighlight } from "./item-highlight";

export function ListBox<T extends object>({
  className,
  render,
  ...props
}: ListBoxProps<T>) {
  return (
    <AriaListBox
      {...props}
      data-slot="list-box"
      render={withItemHighlight(render, { ring: true })}
      className={composeRenderProps(className, (className) =>
        cn(
          "grid max-h-72 w-full min-w-0 gap-1 overflow-y-auto overscroll-contain rounded-lg border border-border bg-card p-1.5 shadow-[var(--shadow-card)] outline-none empty:min-h-24 empty:place-items-center empty:text-sm empty:text-muted-foreground focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-2 focus-visible:outline-ring",
          className,
        ),
      )}
    />
  );
}

export function ListBoxItem({
  className,
  children,
  ...props
}: ListBoxItemProps) {
  return (
    <AriaListBoxItem
      {...props}
      data-slot="list-box-item"
      textValue={
        props.textValue ?? (typeof children === "string" ? children : undefined)
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "group/item flex min-h-11 min-w-0 cursor-pointer items-center justify-between gap-3 rounded-md px-3 py-2 text-sm text-foreground outline-none [overflow-wrap:anywhere] transition-colors duration-150 ease-out-quint selected:bg-accent selected:text-accent-foreground disabled:cursor-default disabled:opacity-50",
          itemHighlightRing,
          className,
        ),
      )}
    >
      {composeRenderProps(children, (content) => (
        <>
          {content}
          <SelectionMark />
        </>
      ))}
    </AriaListBoxItem>
  );
}

export function SelectionMark({ className }: { className?: string }) {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.6}
      strokeLinecap="round"
      strokeLinejoin="round"
      data-slot="selection-mark"
      className={cn("ms-auto size-4 shrink-0", className)}
    >
      <path
        d="M2.75 8 6.25 11.5 13.25 4.5"
        pathLength={1}
        className="[stroke-dasharray:1_2] [stroke-dashoffset:1.01] transition-[stroke-dashoffset] duration-200 ease-out-quint group-selected/item:[stroke-dashoffset:0] motion-reduce:transition-none"
      />
    </svg>
  );
}

"use client";

import { createContext, type ReactNode, useContext } from "react";

export type Size = "xs" | "sm" | "md" | "lg" | "xl";

const SizeContext = createContext<Size | undefined>(undefined);

export function useSize(size?: Size) {
  const inherited = useContext(SizeContext);
  return size ?? inherited;
}

export function SizeProvider({
  size,
  children,
}: {
  size: Size | undefined;
  children: ReactNode;
}) {
  return <SizeContext value={size}>{children}</SizeContext>;
}

"use client";

import {
  Dialog as AriaDialog,
  type DialogProps as AriaDialogProps,
  Popover as AriaPopover,
  type PopoverProps as AriaPopoverProps,
  composeRenderProps,
  DialogTrigger,
  type DialogTriggerProps,
  Heading,
  type HeadingProps,
  OverlayArrow,
  type OverlayArrowProps,
  Text,
  type TextProps,
} from "react-aria-components";
import { cn } from "./utils";
import { SizeProvider } from "./size";

export interface PopoverProps extends AriaPopoverProps {
  "data-slot"?: string;
}

export function PopoverTrigger(props: DialogTriggerProps) {
  return <DialogTrigger {...props} />;
}

export function Popover({
  className,
  children,
  "data-slot": dataSlot = "popover",
  arrowBoundaryOffset = 16,
  ...props
}: PopoverProps) {
  return (
    <AriaPopover
      {...props}
      data-slot={dataSlot}
      arrowBoundaryOffset={arrowBoundaryOffset}
      className={composeRenderProps(className, (className) =>
        cn(
          "group/popover max-w-[calc(100vw-2rem)] overflow-auto overscroll-contain rounded-xl border border-border bg-popover p-4 text-popover-foreground [overflow-wrap:anywhere] shadow-[var(--shadow-float)] outline-none",
          "has-[[data-slot=popover-arrow]]:flex has-[[data-slot=popover-arrow]]:flex-col has-[[data-slot=popover-arrow]]:overflow-visible",
          // React Aria sets data-entering and data-exiting once the placement is
          // known, then waits for these transitions before it unmounts the panel.
          "origin-(--trigger-anchor-point) transition-[opacity,scale,translate] duration-200 ease-out-quint",
          "placement-top:[--popover-shift:0_0.25rem] placement-bottom:[--popover-shift:0_-0.25rem] placement-left:[--popover-shift:0.25rem_0] placement-right:[--popover-shift:-0.25rem_0]",
          "entering:opacity-0 motion-safe:entering:scale-96 motion-safe:entering:[translate:var(--popover-shift)]",
          "exiting:opacity-0 exiting:duration-150 motion-safe:exiting:scale-98 motion-safe:exiting:[translate:var(--popover-shift)]",
          className,
        ),
      )}
    >
      {composeRenderProps(children, (children) => (
        <SizeProvider size={undefined}>
          <div
            data-slot="popover-viewport"
            className="contents group-has-[[data-slot=popover-arrow]]/popover:block group-has-[[data-slot=popover-arrow]]/popover:min-h-0 group-has-[[data-slot=popover-arrow]]/popover:overflow-auto group-has-[[data-slot=popover-arrow]]/popover:overscroll-contain"
          >
            {children}
          </div>
        </SizeProvider>
      ))}
    </AriaPopover>
  );
}

export function PopoverArrow({
  className,
  ...props
}: Omit<OverlayArrowProps, "children">) {
  return (
    <OverlayArrow
      {...props}
      data-slot="popover-arrow"
      className={composeRenderProps(className, (className) =>
        cn("group/arrow", className),
      )}
    >
      <svg
        width={12}
        height={12}
        viewBox="0 0 12 12"
        aria-hidden="true"
        className="block fill-popover stroke-border group-placement-bottom/arrow:rotate-180 group-placement-left/arrow:-rotate-90 group-placement-right/arrow:rotate-90 forced-colors:fill-[Canvas] forced-colors:stroke-[CanvasText]"
      >
        <path d="M0 0 6 6 12 0" />
      </svg>
    </OverlayArrow>
  );
}

export function PopoverDialog({ className, ...props }: AriaDialogProps) {
  return (
    <AriaDialog
      {...props}
      data-slot="popover-dialog"
      className={cn("outline-none", className)}
    />
  );
}

export function PopoverTitle({ className, ...props }: HeadingProps) {
  return (
    <Heading
      {...props}
      slot="title"
      data-slot="popover-title"
      className={cn(
        "text-sm font-semibold leading-5 tracking-[-0.01em] [overflow-wrap:anywhere]",
        className,
      )}
    />
  );
}

export function PopoverDescription({ className, ...props }: TextProps) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="popover-description"
      className={cn(
        "mt-1 block text-sm leading-5 text-muted-foreground [overflow-wrap:anywhere]",
        className,
      )}
    />
  );
}

export function PopoverFooter({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      {...props}
      data-slot="popover-footer"
      className={cn("mt-4 flex flex-wrap justify-end gap-2", className)}
    />
  );
}

"use client";

import { CaretRightIcon } from "@phosphor-icons/react";
import { useSyncExternalStore } from "react";
import {
  Menu as AriaMenu,
  MenuItem as AriaMenuItem,
  composeRenderProps,
  type MenuItemProps,
  type MenuProps,
  MenuTrigger,
  PopoverContext,
  Separator,
  type SeparatorProps,
  SubmenuTrigger,
  useSlottedContext,
} from "react-aria-components";
import { cn } from "./utils";
import { itemHighlightRing, withItemHighlight } from "./item-highlight";
import { SelectionMark } from "./list-box";
import { Popover } from "./popover";

export { MenuTrigger, SubmenuTrigger };

const narrowQuery = "(max-width: 639px)";

function subscribeToNarrow(onChange: () => void) {
  const media = window.matchMedia(narrowQuery);
  media.addEventListener("change", onChange);
  return () => media.removeEventListener("change", onChange);
}

function isNarrowViewport() {
  return window.matchMedia(narrowQuery).matches;
}

export function Menu<T extends object>({ className, ...props }: MenuProps<T>) {
  return (
    <MenuPopover>
      <MenuContent {...props} className={className} />
    </MenuPopover>
  );
}

export function MenuPopover({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Popover>) {
  const context = useSlottedContext(PopoverContext, props.slot);
  const isSubmenu = context?.trigger === "SubmenuTrigger";
  const isNarrow = useSyncExternalStore(
    subscribeToNarrow,
    isNarrowViewport,
    () => false,
  );
  const stacked = isSubmenu && isNarrow;
  return (
    <Popover
      {...props}
      data-slot="menu-popover"
      placement={props.placement ?? (stacked ? "bottom end" : undefined)}
      offset={
        props.offset ?? context?.offset ?? (isSubmenu ? (stacked ? 4 : -2) : 7)
      }
      crossOffset={
        props.crossOffset ?? (isSubmenu && !stacked ? -6 : undefined)
      }
      maxHeight={props.maxHeight ?? 300}
      className={composeRenderProps(className, (className) =>
        cn(
          "min-w-[min(11rem,calc(100vw-2rem))] rounded-lg border-0 p-1.5 ring-1 ring-border/70",
          className,
        ),
      )}
    >
      {children}
    </Popover>
  );
}

export function MenuContent<T extends object>({
  className,
  render,
  ...props
}: MenuProps<T>) {
  return (
    <AriaMenu
      {...props}
      data-slot="menu-content"
      render={withItemHighlight(render, { ring: true })}
      className={composeRenderProps(className, (className) =>
        cn("grid gap-1 outline-none [overflow-wrap:anywhere]", className),
      )}
    />
  );
}

export function MenuItem<T extends object>({
  className,
  children,
  ...props
}: MenuItemProps<T>) {
  return (
    <AriaMenuItem
      {...props}
      textValue={
        props.textValue ?? (typeof children === "string" ? children : undefined)
      }
      data-slot="menu-item"
      className={composeRenderProps(className, (className) =>
        cn(
          "group/item flex min-h-11 cursor-pointer items-center gap-2.5 rounded-md px-3 py-2 text-sm text-foreground outline-none transition-colors duration-150 ease-out-quint open:bg-muted selected:bg-accent selected:text-accent-foreground disabled:cursor-default disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&>[data-slot=kbd]]:ms-auto",
          itemHighlightRing,
          className,
        ),
      )}
    >
      {composeRenderProps(
        children,
        (content, { selectionMode, hasSubmenu }) => (
          <>
            {content}
            {selectionMode !== "none" && !hasSubmenu && <SelectionMark />}
            {hasSubmenu && (
              <CaretRightIcon
                size={16}
                aria-hidden="true"
                className="ms-auto text-muted-foreground rtl:rotate-180"
              />
            )}
          </>
        ),
      )}
    </AriaMenuItem>
  );
}

export function MenuSeparator({ className, ...props }: SeparatorProps) {
  return (
    <Separator
      {...props}
      data-slot="menu-separator"
      className={cn("border-t border-border/70", className)}
    />
  );
}

"use client";

import {
  MenuTrigger as AriaMenuTrigger,
  type MenuTriggerProps,
} from "react-aria-components";

export {
  Menu as ContextMenu,
  MenuContent as ContextMenuContent,
  MenuItem as ContextMenuItem,
  MenuPopover as ContextMenuPopover,
  MenuSeparator as ContextMenuSeparator,
} from "./menu";

export function ContextMenuTrigger(props: Omit<MenuTriggerProps, "trigger">) {
  return <AriaMenuTrigger {...props} trigger="contextMenu" />;
}
